-- Apply only to the named TEST database after review; not run by CI.
CREATE TABLE participants (environment Utf8 NOT NULL, participant_id Utf8 NOT NULL, phone Utf8 NOT NULL, full_name Utf8, age Int32, gender Utf8, city Utf8, visit_krasnodar Utf8, telegram Utf8, email Utf8, preferred_contact Utf8, public_profile_url Utf8, lifecycle_status Utf8, owner Utf8, priority Utf8, next_action Utf8, next_contact_at Timestamp, decision Utf8, internal_comment Utf8, created_at Timestamp NOT NULL, updated_at Timestamp NOT NULL, PRIMARY KEY(environment, participant_id));
CREATE TABLE participant_phone_keys (environment Utf8 NOT NULL, phone Utf8 NOT NULL, participant_id Utf8 NOT NULL, created_at Timestamp NOT NULL, PRIMARY KEY(environment, phone));
CREATE TABLE applications (environment Utf8 NOT NULL, application_id Utf8 NOT NULL, participant_id Utf8 NOT NULL, submitted_at Timestamp NOT NULL, payload_fingerprint Utf8 NOT NULL, form_version Utf8 NOT NULL, request_id Utf8 NOT NULL, full_name Utf8, age Int32, gender Utf8, city Utf8, visit_krasnodar Utf8, phone Utf8, telegram Utf8, email Utf8, preferred_contact Utf8, public_profile_url Utf8, occupation Utf8, life_outside_work Utf8, interests Utf8, what_interested Utf8, event_expectations Utf8, desired_connections Json, values_in_people Utf8, barriers_to_meeting Utf8, social_comfort Utf8, initiative Utf8, acquaintance_scenario Utf8, successful_evening Utf8, return_reason Utf8, unacceptable_behavior Utf8, convenient_days Json, comfortable_price Utf8, source Utf8, PRIMARY KEY(environment, application_id));
CREATE TABLE consents (environment Utf8 NOT NULL, consent_id Utf8 NOT NULL, participant_id Utf8 NOT NULL, application_id Utf8 NOT NULL, consent_type Utf8 NOT NULL, consent_version Utf8 NOT NULL, policy_version Utf8 NOT NULL, form_version Utf8 NOT NULL, consent_text_hash Utf8 NOT NULL, granted Bool NOT NULL, granted_at Timestamp NOT NULL, source Utf8 NOT NULL, request_id Utf8 NOT NULL, PRIMARY KEY(environment, consent_id));
CREATE TABLE technical_logs (environment Utf8 NOT NULL, log_id Utf8 NOT NULL, request_id Utf8 NOT NULL, timestamp Timestamp NOT NULL, application_id Utf8, operation Utf8 NOT NULL, status Utf8 NOT NULL, error_code Utf8, PRIMARY KEY(environment, log_id));
CREATE TABLE audit_log (environment Utf8 NOT NULL, audit_id Utf8 NOT NULL, timestamp Timestamp NOT NULL, request_id Utf8 NOT NULL, application_id Utf8, participant_id Utf8, action Utf8 NOT NULL, PRIMARY KEY(environment, audit_id));
